SqlSelectTableAll:
DECLARE @sql nvarchar(max) =
  N'SELECT * FROM ' + QUOTENAME(@SchemaName) + N'.' + QUOTENAME(@TableName) + N';';
EXEC sp_executesql @sql;

SqlSelectTableTopN:
DECLARE @sql nvarchar(max) =
  N'SELECT TOP (' + CAST(@TopN AS nvarchar(20)) + N') * FROM ' + QUOTENAME(@SchemaName) + N'.' + QUOTENAME(@TableName) + N';';
EXEC sp_executesql @sql;
